"""Deterministic candidate actions for one UI dump (no LLM).

Produces ordered suggestions the explorer may try from the current state:

* tap (clickable / enabled), preferring close/X over ad Install CTAs
* spatial gestures (Phase 12J): swipe up/down/left/right inside detected regions
* open menu (only when interactive)
* wait (splash / empty clickable screens; repeatable)
* back (generated by the engine for backtracking, not listed as forward explore)
"""

from __future__ import annotations

import re
from dataclasses import dataclass, field
from typing import Any, Sequence

from app.modules.exploration.actions import (
    Action,
    BackAction,
    CoordinateTapAction,
    MenuAction,
    SwipeAction,
    TapAction,
    WaitAction,
)
from app.modules.exploration.prior_knowledge import ExplorationPrior
from app.modules.exploration.ui_element import UIElement

# Lazy import avoided: ad_discovery imports UIElement only (no cycle through action_planner).
from app.modules.exploration.ad_discovery import is_ad_trigger_label

_DIALOG_LABELS = re.compile(
    r"^(allow|while using the app|only this time|don.?t allow|deny|ok|okay|yes|"
    r"accept|agree|continue|next|got it|i agree|allow all|allow once)$",
    re.IGNORECASE,
)

# Onboarding / gate CTAs that must be tapped to reach real app content.
# NOTE: "Set As Default" / home-role CTAs are intentionally excluded — granting
# HOME traps exploration on LauncherHomeActivity.
_ONBOARDING_CTA_LABELS = re.compile(
    r"(get started|start now|let.?s go|"
    r"enable|turn on|grant|finish|done|skip intro|continue to app|"
    r"open app|enter app|go to app|i understand|got it|continue|next)",
    re.IGNORECASE,
)

# These make the app the device Home launcher — never tap during exploration.
_HOME_HIJACK_CTA_LABELS = re.compile(
    r"(set as default|set default|set as home|make default|default home|"
    r"make us your default|set now)",
    re.IGNORECASE,
)
_DEFAULT_HOME_DIALOG_RX = re.compile(
    r"default home app|set .+ as your default home|choose.+home app",
    re.IGNORECASE,
)

# Home-shell / system widgets that yank focus out of the app under test.
_ESCAPE_CHROME_LABELS = re.compile(
    r"^(search|google|assistant|voice search|ok google|chrome|play store|"
    r"weather|clock|at a glance)$",
    re.IGNORECASE,
)
_ESCAPE_CHROME_IDS = re.compile(
    r"(ivlens|search_bar|search_button|google_search|qsb|assistant|weather_widget)",
    re.IGNORECASE,
)

# Prefer these so interstitial ads are dismissed instead of followed.
_CLOSE_LABELS = re.compile(
    r"^(close|close ad|dismiss|skip|skip ad|skip video|no thanks|not now|maybe later|"
    r"×|✕|x|︎x)$",
    re.IGNORECASE,
)
_CLOSE_LABEL_LOOSE = re.compile(
    r"\b(close|dismiss|skip(\s+ad)?|skip\s+video)\b",
    re.IGNORECASE,
)
_CLOSE_ID = re.compile(
    r"(close|dismiss|skip|iv_close|btn_close|ad_close|interstitial_close|btn_skip)",
    re.IGNORECASE,
)

# Ad / store CTAs — explore the host app, do not open Play Store / Chrome.
# (Watch/Reward are handled separately as Phase 5 ad-trigger probes, not store CTAs.)
_AD_CTA_LABELS = re.compile(
    r"^(install|download|open|open link|visit|visit site|shop now|buy now|learn more|"
    r"get|get it|get offer|claim|claim now|try now|play now|subscribe|sign up|"
    r"download now|install now|see more|more info)$",
    re.IGNORECASE,
)
_AD_SURFACE_PKG = re.compile(
    r"(gms\.ads|applovin|unity3d\.ads|unity3d\.services\.ads|vungle|ironsource|"
    r"facebook\.ads|mbridge|bytedance|chartboost|adcolony|inmobi|mintegral)",
    re.IGNORECASE,
)
_AD_SURFACE_ID = re.compile(
    r"(adview|ad_frame|ad_container|ad_layout|banner_ad|interstitial|native_ad|"
    r"ads_container|ad_unit)",
    re.IGNORECASE,
)
_PRIMARY_SUBMIT_LABELS = re.compile(
    r"^(save|create|add|done|submit|finish|ok|next|continue)$",
    re.IGNORECASE,
)
_INTERSTITIAL_ACTIVITY = re.compile(
    r"(adactivity|interstitial|fullscreen.?ad|full.?screen.?ad|ads\.adactivity|"
    r"rewarded|appopenad|app_open)",
    re.IGNORECASE,
)
_AD_COPY = re.compile(
    r"(test\s*ad|this is a .{0,12} test ad|advertisement|sponsored|"
    r"adsbygoogle|google\s*ads|adchoices|nice job!?)",
    re.IGNORECASE,
)
_NAV_BACK_LABELS = re.compile(
    r"^(navigate up|back|go back|up)$",
    re.IGNORECASE,
)
_DRAWER_LABELS = re.compile(
    r"^(menu|open menu|open navigation|navigation|navigation drawer|drawer|"
    r"sidebar|hamburger|show navigation drawer|open drawer)$",
    re.IGNORECASE,
)
_DRAWER_ID = re.compile(
    r"(drawer|nav_drawer|navigation_drawer|iv_menu|btn_hamburger|"
    r"hamburger|sidebar|open_drawer|btn_drawer)",
    re.IGNORECASE,
)
# Per-row ⋮ / overflow — NOT the app sidebar. Must never get drawer boost.
_OVERFLOW_LABELS = re.compile(
    r"^(more options|more|options|overflow|edit|delete|remove|share)$",
    re.IGNORECASE,
)
_OVERFLOW_ID = re.compile(
    r"(more_?button|morebutton|overflow|btn_more|iv_more|menu_more|"
    r"delete_?option|edit_?option|action_delete|action_edit)",
    re.IGNORECASE,
)
_CANCEL_DIALOG_LABELS = re.compile(
    r"^(cancel|no|dismiss|keep|don.?t delete|do not delete|close)$",
    re.IGNORECASE,
)
_DESTRUCTIVE_CONFIRM_LABELS = re.compile(
    r"^(delete|remove|uninstall|erase|discard|clear)$",
    re.IGNORECASE,
)
_CREATE_EXPLORE_LABELS = re.compile(
    r"^(add|create|new|\+|fab)$",
    re.IGNORECASE,
)
_CREATE_EXPLORE_LOOSE = re.compile(
    r"\b(add|create|new)\b",
    re.IGNORECASE,
)
_BOTTOM_NAV_ID = re.compile(
    r"(bottom_nav|bottomnav|navigation_bar|navigationbar|tab_layout|tablayout|"
    r"bnav|nav_view|navigationview)",
    re.IGNORECASE,
)
_EXPLORE_DEST_LABELS = re.compile(
    r"\b(home|settings|calendar|clock|stopwatch|schedule|profile|account|"
    r"history|list|inbox|explore|discover)\b",
    re.IGNORECASE,
)

_BROWSER_OR_STORE_PACKAGES = {
    "com.android.chrome",
    "com.chrome.browser",
    "com.android.browser",
    "com.google.android.gms",
    "com.android.vending",
    "com.google.android.packageinstaller",
    "com.android.packageinstaller",
}

_HOME_LAUNCHER_PACKAGES = {
    "com.google.android.apps.nexuslauncher",
    "com.android.launcher3",
    "com.android.launcher",
    "com.android.launcher2",
    "com.google.android.launcher",
    "com.miui.home",
    "com.sec.android.app.launcher",
    "com.huawei.android.launcher",
    "com.oppo.launcher",
    "com.bbk.launcher2",
}

_SETTINGS_PACKAGES = {
    "com.android.settings",
    "com.google.android.settings",
    "com.google.android.permissioncontroller",
    "com.android.permissioncontroller",
}


@dataclass(frozen=True)
class PlannedAction:
    """One concrete gesture plus a stable key for visited_actions tracking."""

    key: str
    action: Action
    kind: str
    priority: int = 0
    label: str = ""
    meta: dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> dict[str, Any]:
        return {
            "key": self.key,
            "kind": self.kind,
            "priority": self.priority,
            "label": self.label,
            "meta": dict(self.meta),
            "action": self.action.to_dict(),
        }


def _quantize_bounds(bounds: tuple[int, int, int, int], step: int = 16) -> str:
    left, top, right, bottom = bounds
    return f"{left // step},{top // step},{right // step},{bottom // step}"


def _element_action_key(kind: str, element: UIElement) -> str:
    return (
        f"{kind}:{element.resource_id or '-'}:"
        f"{_quantize_bounds(element.bounds)}:"
        f"{(element.text or element.content_description or '')[:40]}"
    )


def _is_tiny(element: UIElement, *, min_area: int = 24 * 24) -> bool:
    return element.width * element.height < min_area


def _is_system_chrome(element: UIElement) -> bool:
    rid = (element.resource_id or "").lower()
    return rid.endswith("statusbarbackground") or rid.endswith("navigationbarbackground")


def _is_dialog_button(element: UIElement) -> bool:
    for value in (element.text, element.content_description):
        if value and _DIALOG_LABELS.match(value.strip()):
            return True
    rid = (element.resource_id or "").lower()
    return any(token in rid for token in ("permission_allow", "permission_deny", "btn_positive", "btn_allow"))


def _is_onboarding_cta(element: UIElement) -> bool:
    for value in (element.text, element.content_description):
        if value and _HOME_HIJACK_CTA_LABELS.search(value.strip()):
            return False
        if value and _ONBOARDING_CTA_LABELS.search(value.strip()):
            return True
    rid = (element.resource_id or "").lower()
    if "set_default" in rid or "setdefault" in rid or "btn_default" in rid:
        return False
    return any(
        token in rid
        for token in ("btn_continue", "btn_start", "get_started")
    )


def _is_home_hijack_cta(element: UIElement) -> bool:
    for value in (element.text, element.content_description):
        if value and _HOME_HIJACK_CTA_LABELS.search(value.strip()):
            return True
    rid = (element.resource_id or "").lower()
    return any(
        token in rid
        for token in ("set_default", "setdefault", "btn_default", "tvsetasdefault", "set_as_default")
    )


def looks_like_default_home_gate(
    elements: Sequence[UIElement], *, activity: str | None = None
) -> bool:
    """True for launcher 'Set as Default' pitches / system home-app pickers."""
    act = (activity or "").lower()
    if "defaultapp" in act or "default_app" in act or "launcherhome" in act:
        return True
    blob = " ".join(
        (el.text or el.content_description or "")
        for el in elements[:50]
        if (el.text or el.content_description)
    )
    if _DEFAULT_HOME_DIALOG_RX.search(blob):
        return True
    if _HOME_HIJACK_CTA_LABELS.search(blob) and any(
        "cancel" in (el.text or "").lower() for el in elements if el.clickable
    ):
        return True
    return False


def default_home_pitch_visible(elements: Sequence[UIElement]) -> bool:
    """True when a real 'set as default / home app' prompt is on screen (by its text, not its activity name)."""
    blob = " ".join(
        (el.text or el.content_description or "")
        for el in elements[:60]
        if (el.text or el.content_description)
    )
    if _DEFAULT_HOME_DIALOG_RX.search(blob):
        return True
    return any(
        el.visible and _HOME_HIJACK_CTA_LABELS.search((el.text or el.content_description or "").strip())
        for el in elements
    )


def has_real_app_ui(elements: Sequence[UIElement], *, target_package: str | None) -> bool:
    """True when the screen shows the app's own working UI (several labelled controls).

    An activity named ``LauncherHomeActivity`` is the app's real home screen when the app
    is the device launcher, so the name alone must not make the explorer escape it.
    """
    labelled = [
        el
        for el in elements
        if el.clickable
        and el.enabled
        and el.visible
        and (el.text or el.content_description)
        and (not target_package or el.package == target_package)
    ]
    return len(labelled) >= 3


def _is_escape_chrome(element: UIElement) -> bool:
    """Search / Google / assistant widgets that leave the app for system UI."""
    for value in (element.text, element.content_description):
        if value and _ESCAPE_CHROME_LABELS.match(value.strip()):
            return True
    rid = element.resource_id or ""
    if rid and _ESCAPE_CHROME_IDS.search(rid):
        return True
    return False


def _is_close_control(element: UIElement, *, screen_size: tuple[int, int] | None) -> bool:
    if _is_escape_chrome(element):
        return False
    for value in (element.text, element.content_description):
        if not value:
            continue
        stripped = value.strip()
        if _CLOSE_LABELS.match(stripped):
            return True
        # ImageButton "Close ad" / "Skip Ad" content-desc variants.
        if len(stripped) <= 24 and _CLOSE_LABEL_LOOSE.search(stripped):
            return True
    if element.resource_id and _CLOSE_ID.search(element.resource_id):
        return True
    # Interstitial "X" is often a small unlabeled tap target in the top-right header.
    if screen_size and element.width > 0 and element.height > 0:
        width, height = screen_size
        if width <= 0 or height <= 0:
            return False
        label = (element.text or element.content_description or "").strip()
        # Allow unlabeled or close-ish labels only for geometric X detection.
        if label and not _CLOSE_LABEL_LOOSE.search(label):
            return False
        area_ratio = (element.width * element.height) / float(width * height)
        near_top = element.top <= height * 0.22
        near_right = element.right >= width * 0.72
        near_left = element.left <= width * 0.28
        smallish = area_ratio <= 0.05 and element.width <= width * 0.25 and element.height <= height * 0.14
        if smallish and element.clickable and near_top and (near_right or near_left):
            return True
    return False


def _is_ad_cta(element: UIElement) -> bool:
    for value in (element.text, element.content_description):
        if value and _AD_CTA_LABELS.match(value.strip()):
            return True
    rid = (element.resource_id or "").lower()
    return any(
        token in rid
        for token in (
            "install_button",
            "btn_install",
            "ad_call_to_action",
            "btn_download",
            "cta_button",
            "store_button",
        )
    )


def _is_ad_surface(element: UIElement, *, screen_size: tuple[int, int] | None = None) -> bool:
    """True for ad creatives / WebViews we must not tap (opens Chrome / Play)."""
    if _is_close_control(element, screen_size=screen_size):
        return False
    pkg = element.package or ""
    if pkg and _AD_SURFACE_PKG.search(pkg):
        return True
    rid = element.resource_id or ""
    if rid and _AD_SURFACE_ID.search(rid):
        return True
    blob = f"{element.text} {element.content_description} {rid}".strip()
    if blob and _AD_COPY.search(blob):
        return True
    cls = (element.class_name or "").lower()
    if "webview" in cls:
        lower_blob = blob.lower()
        if any(token in lower_blob for token in ("ad", "ads", "banner", "sponsor", "test")):
            return True
        # Large nearly-fullscreen WebView is usually an interstitial creative.
        if screen_size and element.width > 0 and element.height > 0:
            width, height = screen_size
            if width > 0 and height > 0:
                area_ratio = (element.width * element.height) / float(width * height)
                if area_ratio >= 0.45 and element.clickable:
                    return True
    return False


def _bounds_overlap_ratio(
    a: tuple[int, int, int, int], b: tuple[int, int, int, int]
) -> float:
    ax1, ay1, ax2, ay2 = a
    bx1, by1, bx2, by2 = b
    ix1, iy1 = max(ax1, bx1), max(ay1, by1)
    ix2, iy2 = min(ax2, bx2), min(ay2, by2)
    iw, ih = max(0, ix2 - ix1), max(0, iy2 - iy1)
    inter = iw * ih
    if inter <= 0:
        return 0.0
    area_a = max(1, (ax2 - ax1) * (ay2 - ay1))
    return inter / float(area_a)


def _ad_text_regions(elements: Sequence[UIElement]) -> list[tuple[int, int, int, int]]:
    """Bounds of ad copy (e.g. Google 'Test Ad') plus the whole ad band around it.

    A banner is a full-width strip, but its headline and 'Open' button are narrow nodes
    that the geometry test alone misses. Anything inside the strip is part of the ad, so
    for ad copy near the bottom (or top) of the screen the region is extended to that edge.
    """
    visible = [el for el in elements if el.visible]
    copy = [
        el
        for el in visible
        if (f"{el.text} {el.content_description}".strip()) and _AD_COPY.search(f"{el.text} {el.content_description}")
    ]
    regions: list[tuple[int, int, int, int]] = [el.bounds for el in copy]
    if not copy:
        return regions

    width = max((el.right for el in visible), default=0)
    height = max((el.bottom for el in visible), default=0)
    if width <= 0 or height <= 0:
        return regions

    bottom_copy = [el for el in copy if el.bottom >= height * 0.80]
    top_copy = [el for el in copy if el.top <= height * 0.14]
    if bottom_copy:
        regions.append((0, min(el.top for el in bottom_copy), width, height))
    if top_copy:
        regions.append((0, 0, width, max(el.bottom for el in top_copy)))
    for el in copy:
        if el in bottom_copy or el in top_copy:
            continue
        # Mid-screen (native) ad: the smallest container that holds the copy.
        holders = [
            c
            for c in visible
            if c is not el
            and c.left <= el.left
            and c.top <= el.top
            and c.right >= el.right
            and c.bottom >= el.bottom
            and 0 < c.width * c.height <= 0.5 * width * height
        ]
        if holders:
            best = min(holders, key=lambda c: c.width * c.height)
            regions.append(best.bounds)
    return regions


def _is_banner_ad_slot(
    element: UIElement,
    *,
    screen_size: tuple[int, int] | None,
    ad_regions: Sequence[tuple[int, int, int, int]] | None = None,
) -> bool:
    """Wide short top/bottom bands used by banner ads — never tap these."""
    if _is_close_control(element, screen_size=screen_size):
        return False
    if _is_bottom_nav_control(element):
        return False
    if not screen_size or element.width <= 0 or element.height <= 0:
        return False
    width, height = screen_size
    if width <= 0 or height <= 0:
        return False
    width_r = element.width / float(width)
    height_r = element.height / float(height)
    near_bottom = element.bottom >= height * 0.82
    near_top = element.top <= height * 0.14
    geo = width_r >= 0.55 and 0.035 <= height_r <= 0.22 and (near_bottom or near_top)
    if not geo:
        # Still treat any clickable that mostly covers known ad-copy region as ad.
        if ad_regions:
            for region in ad_regions:
                if _bounds_overlap_ratio(element.bounds, region) >= 0.45:
                    return True
        return False
    blob = f"{element.text} {element.content_description} {element.resource_id}".lower()
    if _AD_COPY.search(blob) or any(token in blob for token in ("adview", "banner", "ads")):
        return True
    cls = (element.class_name or "").lower()
    if "webview" in cls or "adview" in cls:
        return True
    if ad_regions:
        for region in ad_regions:
            if _bounds_overlap_ratio(element.bounds, region) >= 0.35:
                return True
            # Ad text sitting inside this slot.
            rx1, ry1, rx2, ry2 = region
            if (
                rx1 >= element.left - 8
                and ry1 >= element.top - 8
                and rx2 <= element.right + 8
                and ry2 <= element.bottom + 8
            ):
                return True
    return False


def _is_bottom_nav_control(element: UIElement) -> bool:
    rid = element.resource_id or ""
    if rid and _BOTTOM_NAV_ID.search(rid):
        return True
    cls = (element.class_name or "").lower()
    return "bottomnavigation" in cls


def _is_nav_back_control(
    element: UIElement, *, screen_size: tuple[int, int] | None = None
) -> bool:
    """Toolbar / circular back affordance (e.g. Settings top-left)."""
    for value in (element.content_description, element.text):
        if value and _NAV_BACK_LABELS.match(value.strip()):
            return True
    rid = (element.resource_id or "").lower()
    if any(token in rid for token in ("nav_back", "btn_back", "action_bar_back", "toolbar_back")):
        return True
    if "navigate_up" in rid or rid.endswith("/up") or rid.endswith(":id/up"):
        return True
    if not screen_size or not element.clickable:
        return False
    width, height = screen_size
    if width <= 0 or height <= 0:
        return False
    # Top-left compact control — typical circular back on modern app bars.
    near_top = element.top <= height * 0.14
    near_left = element.left <= width * 0.18
    compact = element.width <= width * 0.18 and element.height <= height * 0.11
    if not (near_top and near_left and compact):
        return False
    label = (element.text or element.content_description or "").strip()
    if label and not _NAV_BACK_LABELS.match(label):
        return False
    cls = (element.class_name or "").lower()
    return any(token in cls for token in ("imagebutton", "imageview", "button", "view"))


def _is_drawer_control(
    element: UIElement, *, screen_size: tuple[int, int] | None = None
) -> bool:
    """Hamburger / navigation drawer opener (sidebar entry)."""
    if _is_nav_back_control(element, screen_size=screen_size):
        return False
    if _is_overflow_control(element):
        return False
    for value in (element.content_description, element.text):
        if value and _DRAWER_LABELS.match(value.strip()):
            return True
    rid = element.resource_id or ""
    if rid and _DRAWER_ID.search(rid):
        return True
    if not screen_size or not element.clickable:
        return False
    width, height = screen_size
    if width <= 0 or height <= 0:
        return False
    # Top-left compact unlabeled control that is not back — often the hamburger.
    near_top = element.top <= height * 0.14
    near_left = element.left <= width * 0.18
    compact = element.width <= width * 0.18 and element.height <= height * 0.11
    if not (near_top and near_left and compact):
        return False
    label = (element.text or element.content_description or "").strip()
    if label:
        if _OVERFLOW_LABELS.match(label):
            return False
        return bool(_DRAWER_LABELS.match(label))
    cls = (element.class_name or "").lower()
    return any(token in cls for token in ("imagebutton", "imageview"))


def _is_overflow_control(element: UIElement) -> bool:
    """Per-item ⋮ / Edit / Delete — not navigation."""
    for value in (element.content_description, element.text):
        if value and _OVERFLOW_LABELS.match(value.strip()):
            return True
    rid = (element.resource_id or "").lower()
    return bool(rid and _OVERFLOW_ID.search(rid))


def _is_cancel_dialog_control(element: UIElement) -> bool:
    for value in (element.text, element.content_description):
        if value and _CANCEL_DIALOG_LABELS.match(value.strip()):
            return True
    rid = (element.resource_id or "").lower()
    return any(token in rid for token in ("btn_cancel", "action_cancel", "negative", "btn_no"))


def _is_destructive_confirm_control(element: UIElement) -> bool:
    for value in (element.text, element.content_description):
        if value and _DESTRUCTIVE_CONFIRM_LABELS.match(value.strip()):
            return True
    rid = (element.resource_id or "").lower()
    return any(token in rid for token in ("btn_delete", "action_delete", "btn_remove", "positive_delete"))


def _is_create_explore_control(
    element: UIElement, *, screen_size: tuple[int, int] | None = None
) -> bool:
    """FABs / Add / Create — primary creation entry (labels from live UI + prior)."""
    if _is_overflow_control(element):
        return False
    for value in (element.text, element.content_description):
        if not value:
            continue
        stripped = value.strip()
        if _CREATE_EXPLORE_LABELS.match(stripped) or (
            len(stripped) <= 24 and _CREATE_EXPLORE_LOOSE.search(stripped)
        ):
            return True
    rid = (element.resource_id or "").lower()
    if any(
        token in rid
        for token in ("fab", "btn_add", "btn_create", "action_add", "floating")
    ):
        return True
    # Bottom-right compact unlabeled FAB (common Material + button).
    if not screen_size or not element.clickable:
        return False
    width, height = screen_size
    if width <= 0 or height <= 0:
        return False
    near_bottom = element.bottom >= height * 0.72
    near_right = element.right >= width * 0.78
    compact = element.width <= width * 0.22 and element.height <= height * 0.14
    label = (element.text or element.content_description or "").strip()
    if label or not (near_bottom and near_right and compact):
        return False
    cls = (element.class_name or "").lower()
    return any(token in cls for token in ("imagebutton", "button", "floatingactionbutton"))


def _is_primary_submit_cta(element: UIElement) -> bool:
    for value in (element.text, element.content_description):
        if value and _PRIMARY_SUBMIT_LABELS.match(value.strip()):
            return True
    rid = (element.resource_id or "").lower()
    return any(token in rid for token in ("btn_save", "action_save", "btn_create", "btn_done", "btn_submit"))


def _has_edit_text(elements: Sequence[UIElement]) -> bool:
    for el in elements:
        if not el.visible or not el.enabled:
            continue
        cls = (el.class_name or "").lower()
        if any(token in cls for token in ("edittext", "autocompletetextview", "textinputedittext")):
            return True
    return False


def looks_like_interstitial_ad(
    elements: Sequence[UIElement],
    *,
    activity: str | None = None,
    screen_size: tuple[int, int] | None = None,
) -> bool:
    """Heuristic: fullscreen / AdActivity creative where we should Close or Back.

    Banner-only screens (Settings with a bottom test ad) are NOT interstitials —
    Back would leave the page incorrectly.
    """
    if activity and _INTERSTITIAL_ACTIVITY.search(activity):
        return True
    ad_surfaces = 0
    close_controls = 0
    banner_only = 0
    ad_regions = _ad_text_regions(elements)
    for el in elements:
        if not el.visible:
            continue
        if _is_close_control(el, screen_size=screen_size):
            close_controls += 1
        if _is_banner_ad_slot(el, screen_size=screen_size, ad_regions=ad_regions):
            banner_only += 1
            continue
        if _is_ad_surface(el, screen_size=screen_size) or _is_ad_cta(el):
            ad_surfaces += 1
    if ad_surfaces >= 1 and close_controls >= 1:
        return True
    if ad_surfaces >= 2:
        return True
    # Single large ad surface covering most of the screen.
    if screen_size and ad_surfaces == 1:
        width, height = screen_size
        if width > 0 and height > 0:
            for el in elements:
                if not el.visible or not _is_ad_surface(el, screen_size=screen_size):
                    continue
                if (el.width * el.height) / float(width * height) >= 0.5:
                    return True
    return False


def _is_explore_destination(element: UIElement) -> bool:
    blob = f"{element.text} {element.content_description}".strip()
    if blob and _EXPLORE_DEST_LABELS.search(blob):
        return True
    rid = (element.resource_id or "").lower()
    return any(token in rid for token in ("tab_", "nav_", "menu_"))


def _is_permission_package(package: str) -> bool:
    lowered = (package or "").lower()
    return "permissioncontroller" in lowered or lowered.endswith(".permissioncontroller")


def is_external_browser_or_store(activity: str | None, package: str | None = None) -> bool:
    """True when focus has left the target app into Chrome / Play Store / installer."""
    blob = f"{activity or ''} {package or ''}".lower()
    if any(p in blob for p in _BROWSER_OR_STORE_PACKAGES):
        return True
    if "chrome" in blob or "vending" in blob or "market" in blob:
        return True
    return False


def is_home_launcher(
    activity: str | None = None,
    package: str | None = None,
    *,
    target_package: str | None = None,
) -> bool:
    """True when the device is showing the *system* home / launcher screen.

    The target app may register its own ``LauncherHomeActivity`` after becoming
    the default Home app — that must NOT be treated as leaving the app.
    """
    pkg = package if isinstance(package, str) else ""
    pkg = pkg.strip()
    if not pkg and isinstance(activity, str) and "/" in activity:
        pkg = activity.split("/", 1)[0]
    target = target_package if isinstance(target_package, str) else ""
    if target and pkg and pkg == target:
        return False
    lowered = pkg.lower()
    if lowered in _HOME_LAUNCHER_PACKAGES:
        return True
    # Only treat unknown *packages* with launcher in the name as home shells —
    # never match on activity paths like ``.launcher.LauncherHomeActivity``.
    if lowered.endswith(".launcher") or lowered.endswith(".launcher3") or lowered.endswith(".launcher2"):
        return True
    blob = activity.lower() if isinstance(activity, str) else ""
    if target and target.lower() in blob:
        return False
    return "nexuslauncher" in blob or "android.launcher3" in blob or "apps.nexuslauncher" in blob


def is_transient_escape_package(package: str | None = None, activity: str | None = None) -> bool:
    """Packages we leave briefly (Search, Assistant) and should Back out of — not relaunch."""
    pkg = (package or "").strip()
    if not pkg and activity and "/" in activity:
        pkg = activity.split("/", 1)[0]
    lowered = pkg.lower()
    if lowered in {
        "com.google.android.googlequicksearchbox",
        "com.google.android.apps.googleassistant",
        "com.google.android.inputmethod.latin",
        "com.google.android.apps.messaging",
    }:
        return True
    blob = f"{activity or ''} {pkg}".lower()
    return "googlequicksearchbox" in blob or "googleassistant" in blob or "assistant" in lowered


def is_system_settings(activity: str | None = None, package: str | None = None) -> bool:
    pkg = (package or "").strip()
    if not pkg and activity and "/" in activity:
        pkg = activity.split("/", 1)[0]
    if pkg in _SETTINGS_PACKAGES:
        return True
    blob = f"{activity or ''} {pkg}".lower()
    return "android.settings" in blob or "settings.intelligence" in blob


def count_clickables(elements: Sequence[UIElement]) -> int:
    return sum(
        1
        for el in elements
        if el.clickable and el.enabled and el.visible and not _is_tiny(el) and not _is_system_chrome(el)
    )


def is_splash_like(elements: Sequence[UIElement], *, activity: str | None = None) -> bool:
    """True when the screen has no meaningful taps (typical splash / loader)."""
    if activity and "splash" in activity.lower():
        return True
    return count_clickables(elements) == 0


def plan_actions(
    elements: Sequence[UIElement],
    *,
    prior: ExplorationPrior | None = None,
    screen_size: tuple[int, int] | None = None,
    splash_wait_seconds: float = 3.0,
    wait_attempt: int = 0,
    include_menu: bool = True,
    include_wait_if_empty: bool = True,
    include_screen_swipes_when_empty: bool = False,
    include_center_tap_when_empty: bool = True,
    max_taps: int = 40,
    activity: str | None = None,
    prefer_ad_triggers: bool = False,
    region_memory: Any | None = None,
) -> list[PlannedAction]:
    """Return forward actions sorted by descending priority."""
    planned: list[PlannedAction] = []
    seen_keys: set[str] = set()
    idle = is_splash_like(elements, activity=activity)
    target_pkg = prior.package_name if prior else None

    active_kind: str | None = None
    if prior is not None and hasattr(prior, "active_goal"):
        try:
            active = prior.active_goal()
            active_kind = (active or {}).get("kind")
        except Exception:
            active_kind = None

    clickables = [
        el
        for el in elements
        if el.clickable
        and el.enabled
        and el.visible
        and not _is_tiny(el)
        and not _is_system_chrome(el)
    ]

    scored: list[tuple[int, UIElement, bool]] = []
    formish = _has_edit_text(elements)
    ad_regions = _ad_text_regions(elements)
    meaningful_taps = 0
    for el in clickables:
        # Never plan taps that open ad links / store — dismiss via close/Back only.
        if (
            _is_ad_cta(el)
            or _is_ad_surface(el, screen_size=screen_size)
            or _is_banner_ad_slot(el, screen_size=screen_size, ad_regions=ad_regions)
        ):
            continue

        bonus = prior.label_priority(el.text, el.resource_id, el.content_description) if prior else 0
        ad_trigger = False
        if el.text or el.content_description:
            bonus += 3
        if el.resource_id:
            bonus += 1

        if _is_close_control(el, screen_size=screen_size):
            bonus += 120
        elif _is_permission_package(el.package or "") or (
            el.resource_id and "permission_" in (el.resource_id or "").lower()
        ):
            # System permission / role dialogs must beat in-app Settings/Home chrome.
            bonus += 140
            meaningful_taps += 1
        elif _is_cancel_dialog_control(el):
            # Leave Delete/Edit confirm dialogs without destroying content.
            # Also dismiss default-home pickers (Cancel >> Set as default).
            bonus += 135
            meaningful_taps += 1
        elif _is_home_hijack_cta(el):
            # Never become device Home during exploration.
            bonus -= 200
        elif _is_drawer_control(el, screen_size=screen_size):
            # Sidebar / hamburger — highest when nav map says open drawer next.
            bonus += 145 if active_kind == "sidebar" else 110
            meaningful_taps += 1
        elif _is_create_explore_control(el, screen_size=screen_size):
            # Prefer create when that is the active map step; otherwise demote vs drawer.
            if active_kind == "create":
                bonus += 125
            elif active_kind == "sidebar":
                bonus += 40
            else:
                bonus += 115
            meaningful_taps += 1
        elif _is_nav_back_control(el, screen_size=screen_size):
            # Leave nested pages via toolbar back instead of swiping.
            bonus += 95
            meaningful_taps += 1
        elif _is_bottom_nav_control(el) or _is_explore_destination(el):
            dest_bonus = 70
            if active_kind == "home" and "home" in (
                f"{el.text} {el.content_description} {el.resource_id}".lower()
            ):
                dest_bonus = 120
            elif active_kind == "settings" and "setting" in (
                f"{el.text} {el.content_description} {el.resource_id}".lower()
            ):
                dest_bonus = 110
            bonus += dest_bonus
            meaningful_taps += 1
        elif _is_onboarding_cta(el):
            bonus += 130 if active_kind == "onboarding" else 110
        elif formish and _is_primary_submit_cta(el):
            bonus += 100
            meaningful_taps += 1
        elif _is_destructive_confirm_control(el) or _is_overflow_control(el):
            # Never prioritize ⋮ / Edit / Delete over real navigation or create.
            bonus -= 160
        elif _is_dialog_button(el):
            bonus += 50
        elif _is_escape_chrome(el):
            bonus -= 120
        elif el.text or el.content_description:
            meaningful_taps += 1

        if prefer_ad_triggers and is_ad_trigger_label(el.text, el.resource_id, el.content_description):
            bonus += 35
            ad_trigger = True

        if target_pkg and el.package and el.package != target_pkg:
            if _is_permission_package(el.package):
                bonus += 25
            elif is_external_browser_or_store(activity, el.package):
                bonus -= 100
            elif _is_escape_chrome(el):
                bonus -= 120
            else:
                bonus += 5

        # In the default-app / role picker, prefer rows that name our package.
        if target_pkg and is_system_settings(activity, el.package if el.package != target_pkg else None):
            label_blob = f"{el.text} {el.content_description} {el.resource_id}".lower()
            pkg_token = target_pkg.rsplit(".", 1)[-1].lower()
            if target_pkg.lower() in label_blob or (pkg_token and pkg_token in label_blob):
                bonus += 100
            elif prior and prior.package_name:
                # Match human app labels from preferred list loosely.
                for preferred in prior.preferred_labels[:8]:
                    if preferred and preferred.lower() in label_blob:
                        bonus += 80
                        break

        scored.append((bonus, el, ad_trigger))
    scored.sort(key=lambda item: (-item[0], item[1].top, item[1].left))

    for bonus, el, ad_trigger in scored[:max_taps]:
        if bonus < -40 and any(b >= 0 for b, _, _ in scored):
            continue
        key = _element_action_key("tap", el)
        if key in seen_keys:
            continue
        seen_keys.add(key)
        planned.append(
            PlannedAction(
                key=key,
                action=TapAction(element=el),
                kind="tap",
                priority=100 + bonus,
                label=el.label(),
                meta={
                    "text": el.text,
                    "content_description": el.content_description,
                    "resource_id": el.resource_id,
                    "bounds": list(el.bounds),
                    "package": el.package,
                    "prior_bonus": bonus,
                    "is_close": _is_close_control(el, screen_size=screen_size),
                    "is_onboarding_cta": _is_onboarding_cta(el),
                    "is_home_hijack_cta": _is_home_hijack_cta(el),
                    "is_escape_chrome": _is_escape_chrome(el),
                    "is_ad_cta": False,
                    "is_banner_ad": False,
                    "is_nav_back": _is_nav_back_control(el, screen_size=screen_size),
                    "is_drawer": _is_drawer_control(el, screen_size=screen_size),
                    "is_create_explore": _is_create_explore_control(
                        el, screen_size=screen_size
                    ),
                    "is_overflow": _is_overflow_control(el),
                    "is_cancel_dialog": _is_cancel_dialog_control(el),
                    "is_destructive_confirm": _is_destructive_confirm_control(el),
                    "is_primary_submit": _is_primary_submit_cta(el),
                    "ad_trigger": ad_trigger,
                },
            )
        )

    # Prefer labeled taps / create / back over blind swipes — but keep swipes
    # competitive so a screen with many taps still scrolls after a couple of taps.
    swipe_priority = 28 if meaningful_taps >= 2 else 48
    screen_swipe_priority = 22 if meaningful_taps >= 2 else 36
    if active_kind in {"home", "sidebar", "destination", "feature"}:
        swipe_priority = max(swipe_priority, 42)
        screen_swipe_priority = max(screen_swipe_priority, 38)
    elif active_kind == "onboarding":
        # Past gates the fallback list is full of taps; still try a scroll.
        screen_swipe_priority = max(screen_swipe_priority, 30)

    if idle:
        if include_wait_if_empty:
            key = f"wait:splash:{wait_attempt}"
            planned.append(
                PlannedAction(
                    key=key,
                    action=WaitAction(seconds=splash_wait_seconds),
                    kind="wait",
                    priority=200,
                    label=f"wait {splash_wait_seconds}s for splash/loading (poll {wait_attempt})",
                    meta={"seconds": splash_wait_seconds, "attempt": wait_attempt},
                )
            )
        if include_center_tap_when_empty and screen_size and wait_attempt == 0:
            width, height = screen_size
            if width > 0 and height > 0:
                key = "tap:center:splash"
                planned.append(
                    PlannedAction(
                        key=key,
                        action=CoordinateTapAction(x=width // 2, y=height // 2),
                        kind="tap",
                        priority=90,
                        label="tap center (dismiss splash)",
                        meta={"x": width // 2, "y": height // 2},
                    )
                )
        planned.sort(key=lambda item: (-item.priority, item.key))
        return planned

    # Phase 12J — spatial gesture candidates (vertical + horizontal + multi-region).
    try:
        from app.core.config import settings as _settings
        from app.modules.exploration.spatial.gesture_planner import plan_gesture_actions
        from app.modules.exploration.spatial.spatial_analyzer import analyze_regions

        regions = analyze_regions(elements, screen_size=screen_size)
        memory = region_memory
        if memory is None and prior is not None:
            memory = getattr(prior, "region_memory", None)
        gesture_actions = plan_gesture_actions(
            regions,
            screen_size=screen_size,
            memory=memory,
            meaningful_taps=meaningful_taps,
            edge_margin=float(
                getattr(_settings, "exploration_gesture_edge_margin", 0.15) or 0.15
            ),
            distance_ratio=float(
                getattr(_settings, "exploration_gesture_distance_ratio", 0.7) or 0.7
            ),
            max_per_region=int(
                getattr(_settings, "exploration_gesture_max_per_region", 4) or 4
            ),
            no_change_limit=int(
                getattr(_settings, "exploration_gesture_no_change_limit", 2) or 2
            ),
        )
        # Align base priorities with journey soft boosts.
        for item in gesture_actions:
            if item.key in seen_keys:
                continue
            seen_keys.add(item.key)
            # Soft boost when journey wants content exploration.
            boosted = item.priority
            if active_kind in {"home", "sidebar", "destination", "feature"}:
                boosted = max(boosted, swipe_priority)
            planned.append(
                PlannedAction(
                    key=item.key,
                    action=item.action,
                    kind=item.kind,
                    priority=boosted,
                    label=item.label,
                    meta=dict(item.meta or {}),
                )
            )
    except Exception:
        # Deterministic fallback: previous up/down-only behavior.
        scrollables = [el for el in elements if el.scrollable and el.visible and el.enabled]
        for direction in ("up", "down"):
            if scrollables:
                target = max(scrollables, key=lambda el: el.width * el.height)
                key = f"swipe:{direction}:scroll:{_quantize_bounds(target.bounds)}"
                if key not in seen_keys:
                    seen_keys.add(key)
                    cx, cy = target.center
                    inset = max(20, target.height // 4)
                    if direction == "up":
                        start, end = (cx, target.bottom - inset), (cx, target.top + inset)
                    else:
                        start, end = (cx, target.top + inset), (cx, target.bottom - inset)
                    planned.append(
                        PlannedAction(
                            key=key,
                            action=SwipeAction(start=start, end=end, direction=direction),
                            kind=f"swipe_{direction}",
                            priority=swipe_priority,
                            label=f"swipe {direction} on scrollable",
                            meta={"bounds": list(target.bounds), "direction": direction},
                        )
                    )
            elif screen_size and (include_screen_swipes_when_empty or True):
                key = f"swipe:{direction}:screen"
                if key not in seen_keys:
                    seen_keys.add(key)
                    planned.append(
                        PlannedAction(
                            key=key,
                            action=SwipeAction(direction=direction),  # type: ignore[arg-type]
                            kind=f"swipe_{direction}",
                            priority=screen_swipe_priority,
                            label=f"swipe {direction} (screen)",
                            meta={"direction": direction},
                        )
                    )

    if include_menu:
        key = "open_menu"
        if key not in seen_keys:
            seen_keys.add(key)
            # Soft-key MENU is a fallback when no hamburger node is exposed.
            # Prefer menu while on home/sidebar so we explore chrome instead of
            # low-value Back / wait that can leave the app.
            if active_kind == "sidebar":
                menu_priority = 85
            elif active_kind in {"home", "settings"}:
                menu_priority = 55
            else:
                menu_priority = 15
            planned.append(
                PlannedAction(
                    key=key,
                    action=MenuAction(),
                    kind="open_menu",
                    priority=menu_priority,
                    label="open menu",
                    meta={"active_goal_kind": active_kind},
                )
            )

    planned.sort(key=lambda item: (-item.priority, item.key))
    return planned


def apply_swipe_budget(
    candidates: Sequence[PlannedAction], *, swipes_done: int, budget: int
) -> list[PlannedAction]:
    """Drop swipes once a screen has used its swipe budget, so the agent taps something instead.

    Swipes are kept when nothing else is left to do on the screen.
    """
    items = list(candidates)
    if budget <= 0 or swipes_done < budget:
        return items
    taps = [c for c in items if not str(c.kind).startswith("swipe")]
    return taps or items


def back_action() -> PlannedAction:
    return PlannedAction(
        key="back",
        action=BackAction(),
        kind="back",
        priority=0,
        label="back",
    )


def relaunch_action(*, reason: str = "system_home") -> PlannedAction:
    """Synthetic action: engine recovers into the target package (no arbitrary ADB).

    For ``system_home``, Explorer prefers swipe-right on the launcher (default-app
    workspace) before soft-resume.
    """
    return PlannedAction(
        key=f"relaunch:{reason}",
        action=BackAction(),  # placeholder; explorer handles kind=relaunch specially
        kind="relaunch",
        priority=1000,
        label=f"relaunch ({reason})",
        meta={"reason": reason, "prefer_home_swipe": reason in {"system_home", "escape_home_shell"}},
    )
